from kubernetes import client, config
from langchain_core.tools import tool

config.load_kube_config()


@tool
def provision_team_namespace(namespace_name: str, team_group_name: str, cost_center: str = "") -> str:
    """Create a team namespace and grant the team's group edit access in it."""
    core_api_client = client.CoreV1Api()
    rbac_api_client = client.RbacAuthorizationV1Api()
    namespace_labels = {"team": team_group_name, "managed-by": "platform-agent"}
    if cost_center:
        namespace_labels["cost-center"] = cost_center
    namespace_manifest = client.V1Namespace(
        metadata=client.V1ObjectMeta(name=namespace_name, labels=namespace_labels)
    )
    created_namespace = core_api_client.create_namespace(body=namespace_manifest)
    role_binding_name = f"{team_group_name}-edit"
    team_group_subject = client.RbacV1Subject(
        kind="Group",
        name=team_group_name,
        api_group="rbac.authorization.k8s.io",
    )
    role_binding_manifest = client.V1RoleBinding(
        metadata=client.V1ObjectMeta(name=role_binding_name, namespace=namespace_name),
        role_ref=client.V1RoleRef(
            api_group="rbac.authorization.k8s.io", kind="ClusterRole", name="edit"
        ),
        subjects=[team_group_subject],
    )
    created_role_binding = rbac_api_client.create_namespaced_role_binding(
        namespace=namespace_name, body=role_binding_manifest
    )
    return (
        f"Namespace {created_namespace.metadata.name} created; group {team_group_name} "
        f"bound to ClusterRole 'edit' via RoleBinding {created_role_binding.metadata.name}."
    )

import os
from dataclasses import dataclass, field

import requests
from kubernetes import client, config
from kubernetes.client.rest import ApiException

config.load_kube_config()

OPS_WEBHOOK_URL = os.environ["K8S_OPS_WEBHOOK_URL"]


@dataclass
class PodPurgeResult:
    namespace: str
    deleted: list = field(default_factory=list)
    failed: dict = field(default_factory=dict)
    notified: bool = False


def _send_report(result: PodPurgeResult) -> bool:
    payload = {
        "event": "pod_purge",
        "namespace": result.namespace,
        "deleted": result.deleted,
        "failed": result.failed,
        "text": (
            f"Purged {len(result.deleted)} pod(s) in {result.namespace}; "
            f"{len(result.failed)} failure(s)."
        ),
    }
    try:
        response = requests.post(OPS_WEBHOOK_URL, json=payload, timeout=10)
        response.raise_for_status()
    except requests.RequestException:
        return False
    return True


def purge_failed_pods_and_notify(namespace: str, pod_names: list, grace_period_seconds: int = 0) -> PodPurgeResult:
    core = client.CoreV1Api()
    result = PodPurgeResult(namespace=namespace)
    options = client.V1DeleteOptions(
        grace_period_seconds=grace_period_seconds,
        propagation_policy="Background",
    )
    for pod_name in pod_names:
        try:
            core.delete_namespaced_pod(
                name=pod_name,
                namespace=namespace,
                body=options,
            )
            result.deleted.append(pod_name)
        except ApiException as exc:
            if exc.status == 404:
                result.failed[pod_name] = "not found"
            else:
                result.failed[pod_name] = f"{exc.status} {exc.reason}"
    result.notified = _send_report(result)
    return result
